import { Component, OnDestroy, OnInit } from '@angular/core';
import { Subject, interval } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

@Component({ selector: 'app-ticker', template: '{{ count }}' })
export class TickerComponent implements OnInit, OnDestroy {
  count = 0;
  private destroy$ = new Subject<void>();

  ngOnInit(): void {
    interval(1000)
      .pipe(takeUntil(this.destroy$)) // must be last
      .subscribe(v => (this.count = v));
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}

import { Component } from '@angular/core';
import { FormControl } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { debounceTime, distinctUntilChanged, filter, map, switchMap } from 'rxjs/operators';

@Component({
  selector: 'app-search',
  template: `
    <input [formControl]="term" />
    <ul><li *ngFor="let r of results$ | async">{{ r }}</li></ul>
  `,
})
export class SearchComponent {
  term = new FormControl('');
  results$: Observable<string[]> = this.term.valueChanges.pipe(
    debounceTime(300),
    map(t => (t ?? '').trim()),
    distinctUntilChanged(),
    filter(t => t.length > 0),
    switchMap(t => this.http.get<string[]>(`/api/search?q=${t}`))
  );
  constructor(private http: HttpClient) {}
}

import { fromEvent } from 'rxjs';
import { switchMap, mergeMap, concatMap, exhaustMap } from 'rxjs/operators';

const clicks$ = fromEvent(document.getElementById('save')!, 'click');

// Prevent double-submit: ignore clicks while a save is in progress
clicks$.pipe(exhaustMap(() => saveToServer())).subscribe();

// Latest wins, cancel previous
clicks$.pipe(switchMap(() => saveToServer())).subscribe();

// Strict order, one after another
clicks$.pipe(concatMap(() => saveToServer())).subscribe();

// Fire all in parallel
clicks$.pipe(mergeMap(() => saveToServer())).subscribe();

declare function saveToServer(): import('rxjs').Observable<unknown>;

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export interface CartState { items: string[]; count: number; }

@Injectable({ providedIn: 'root' })
export class CartService {
  private state$ = new BehaviorSubject<CartState>({ items: [], count: 0 });

  // read-only stream
  readonly cart$: Observable<CartState> = this.state$.asObservable();

  get snapshot(): CartState { return this.state$.value; }

  addItem(item: string): void {
    const current = this.state$.value;
    const items = [...current.items, item];
    this.state$.next({ items, count: items.length });
  }
}

