import { Directive, ElementRef, HostListener, Input, Renderer2 } from '@angular/core';

@Directive({ selector: '[appHighlight]', standalone: true })
export class HighlightDirective {
  @Input('appHighlight') color = 'yellow';

  constructor(private el: ElementRef<HTMLElement>, private r: Renderer2) {}

  @HostListener('mouseenter') onEnter(): void {
    this.r.setStyle(this.el.nativeElement, 'background-color', this.color);
  }

  @HostListener('mouseleave') onLeave(): void {
    this.r.removeStyle(this.el.nativeElement, 'background-color');
  }
}
// Usage: <p [appHighlight]="'lightblue'">Hover me</p>

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'filterBy', standalone: true /* pure: true by default */ })
export class FilterByPipe implements PipeTransform {
  transform(items: string[] | null, term: string): string[] {
    if (!items) return [];
    const t = (term ?? '').toLowerCase();
    return t ? items.filter(i => i.toLowerCase().includes(t)) : items;
  }
}
// Pure works ONLY if the list is replaced immutably (items = [...newItems]).
// Impure version (re-runs every CD cycle) would be: @Pipe({ name: 'filterBy', pure: false })

import { Component } from '@angular/core';
import { FormBuilder, Validators, AbstractControl, ValidationErrors } from '@angular/forms';

function matchPasswords(group: AbstractControl): ValidationErrors | null {
  const pw = group.get('password')?.value;
  const confirm = group.get('confirm')?.value;
  return pw === confirm ? null : { mismatch: true };
}

